294	  const persist = (next: RefGame[]) => {
295	    setRefGames(next);
296	    updateProject.mutate({ projectId, data: { referenceGames: JSON.stringify(next) } as any });
297	  };
298	
299	  const addGame = () => {
300	    if (!draft.name.trim()) return;
301	    persist([...refGames, { ...draft }]);
302	    setDraft({ name: "", borrowing: "", avoiding: "" });
303	    setShowForm(false);
