321	      const next = refGames.map((g, j) =>
322	        j === i ? { ...g, researchId: research.id, gameData } : g
323	      );
324	      persist(next);
325	      qc.invalidateQueries({ queryKey: getListResearchQueryKey(projectId) });
326	      toast({ title: `${game.name} researched`, description: "Full breakdown saved to your notes." });
327	    } catch (err) {
328	      toast({ title: "Lookup failed", description: err instanceof Error ? err.message : String(err), variant: "destructive" });
329	    } finally {
330	      setLookingUp(null);
331	    }
332	  };
333	
334	  return (
335	    <div className="space-y-4">
336	      <div className="flex items-center justify-between">
337	        <div>
338	          <h3 className="font-semibold text-base flex items-center gap-2">
339	            <Heart className="h-4 w-4 text-rose-400" /> Games that shaped your vision
