/* ── InspirationShelf ────────────────────────────────────────────────── */

function InspirationShelf({ projectId, workspaceSlug }: { projectId: number; workspaceSlug?: string }) {
  const { data: project } = useGetProject(projectId);
  const updateProject = useUpdateProject();
  const qc = useQueryClient();
  const { toast } = useToast();
  const [, setLocation] = useLocation();

  const [refGames, setRefGames] = useState<RefGame[]>([]);
  const [draft, setDraft] = useState({ name: "", borrowing: "", avoiding: "" });
  const [showForm, setShowForm] = useState(false);
  const [lookingUp, setLookingUp] = useState<string | null>(null); // game id
  const [reverseTarget, setReverseTarget] = useState<RefGame | null>(null);
  const [reverseDirection, setReverseDirection] = useState("");
  const [reversing, setReversing] = useState(false);
  const initRef = useRef(false);

  useEffect(() => {
    if (project && !initRef.current) {
      setRefGames(parseRefGames((project as any).referenceGames));
      initRef.current = true;
    }
  }, [project]);

  const persist = (next: RefGame[]) => {
    setRefGames(next);
    updateProject.mutate({ projectId, data: { referenceGames: JSON.stringify(next) } as any });
  };

  const addGame = () => {
    if (!draft.name.trim()) return;
    persist([...refGames, { id: crypto.randomUUID(), ...draft }]);
    setDraft({ name: "", borrowing: "", avoiding: "" });
    setShowForm(false);
  };

  const removeGame = (id: string) => persist(refGames.filter((g) => g.id !== id));

  const lookUpGame = async (id: string, clearExisting = false) => {
    const game = refGames.find((g) => g.id === id);
    if (!game) return;
    setLookingUp(id);
    // Optionally clear existing data so the card returns to un-researched state while loading
    if (clearExisting) {
      persist(refGames.map((g) => g.id === id ? { ...g, gameData: undefined, researchId: undefined } : g));
    }
    try {
      const res = await fetch(`${apiBase()}/api/projects/${projectId}/research/game-lookup`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({ gameName: game.name, borrowing: game.borrowing, avoiding: game.avoiding }),
      });
      if (!res.ok) throw new Error(await res.text());
      const { research, gameData } = await res.json() as { research: { id: number }; gameData: GameData };
      // Re-read latest refGames from current state
      setRefGames((prev) => {
        const next = prev.map((g) => g.id === id ? { ...g, researchId: research.id, gameData } : g);
        updateProject.mutate({ projectId, data: { referenceGames: JSON.stringify(next) } as any });
        return next;
      });
      qc.invalidateQueries({ queryKey: getListResearchQueryKey(projectId) });
      toast({ title: `${game.name} researched`, description: "Full breakdown saved to your notes." });
    } catch (err) {
      toast({ title: "Lookup failed", description: err instanceof Error ? err.message : String(err), variant: "destructive" });
    } finally {
      setLookingUp(null);
    }
  };

  const reverseEngineer = async () => {
    if (!reverseTarget || !workspaceSlug) return;
    setReversing(true);
    try {
      const gd = reverseTarget.gameData;
      const mechanicsHint = gd?.keyMechanics?.join(", ") ?? "";
      const lessonsHint = gd?.designLessons ?? "";
      const prompt = [
        `Reverse-engineer and reimagine "${reverseTarget.name}" as a fresh, original board game.`,
        mechanicsHint && `Core mechanics to adapt: ${mechanicsHint}.`,
        lessonsHint && `Design insight: ${lessonsHint}.`,
        reverseDirection.trim() && `New direction: ${reverseDirection.trim()}.`,
        `Create a playable prototype with a compelling theme, clear win condition, and balanced player roles. Make it distinctly different from "${reverseTarget.name}".`,
      ].filter(Boolean).join(" ");

      const out = await workspacesApi.generate(workspaceSlug, { prompt });
      setReverseTarget(null);
      setReverseDirection("");
      toast({ title: "New project created!", description: out.project.name });
      setLocation(`/${out.workspaceSlug}/${out.project.slug ?? out.project.id}`);
    } catch (err) {
      toast({ title: "Reverse engineer failed", description: err instanceof Error ? err.message : String(err), variant: "destructive" });
    } finally {
      setReversing(false);
    }
  };

  return (
    <div className="space-y-4">
      {/* Section header */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="font-semibold text-base flex items-center gap-2">
            <Heart className="h-4 w-4 text-rose-400" /> Games that shaped your vision
          </h3>
          <p className="text-xs text-muted-foreground mt-0.5">
            Add a game, hit <span className="text-primary font-medium">Research with AI</span> for a full breakdown, then{" "}
            <span className="text-violet-400 font-medium">Reverse Engineer</span> it into a new project.
          </p>
        </div>
        {!showForm && (
          <Button size="sm" variant="outline" className="gap-1.5 shrink-0" onClick={() => setShowForm(true)}>
            <Plus className="h-3.5 w-3.5" /> Add a game
          </Button>
        )}
      </div>

      {/* Add game form */}
      {showForm && (
        <div className="rounded-xl border border-primary/30 bg-primary/5 p-4 space-y-3">
          <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Add a reference game</p>
          <Input
            placeholder="Game name (e.g. Wingspan, Catan, Dominion…)"
            value={draft.name}
            onChange={(e) => setDraft((d) => ({ ...d, name: e.target.value }))}
            autoFocus
            onKeyDown={(e) => e.key === "Enter" && addGame()}
          />
          <Input
            placeholder="What's the best part you want to borrow? (optional)"
            value={draft.borrowing}
            onChange={(e) => setDraft((d) => ({ ...d, borrowing: e.target.value }))}
          />
          <Input
            placeholder="What would you do differently? (optional)"
            value={draft.avoiding}
            onChange={(e) => setDraft((d) => ({ ...d, avoiding: e.target.value }))}
          />
          <div className="flex gap-2 pt-1">
            <Button size="sm" onClick={addGame} disabled={!draft.name.trim()}>Add game</Button>
            <Button size="sm" variant="ghost" onClick={() => setShowForm(false)}>Cancel</Button>
          </div>
        </div>
      )}

      {/* Drag-and-drop list */}
      {refGames.length > 0 && (
        <Reorder.Group
          axis="y"
          values={refGames}
          onReorder={persist}
          className="space-y-3"
          as="div"
        >
          {refGames.map((rg) => (
            <DraggableGameCard
              key={rg.id}
              game={rg}
              onRemove={() => removeGame(rg.id)}
              onResearch={() => lookUpGame(rg.id)}
              onReResearch={() => lookUpGame(rg.id, true)}
              onReverseEngineer={() => { setReverseTarget(rg); setReverseDirection(""); }}
              researching={lookingUp === rg.id}
              canReverseEngineer={Boolean(workspaceSlug && rg.gameData)}
            />
          ))}
        </Reorder.Group>
      )}

      {/* Empty state */}
      {refGames.length === 0 && !showForm && (
        <button
          onClick={() => setShowForm(true)}
          className="w-full rounded-xl border-2 border-dashed border-border hover:border-primary/40 p-8 text-center text-muted-foreground hover:text-foreground transition-colors group"
        >
          <Heart className="h-8 w-8 mx-auto mb-2 opacity-30 group-hover:opacity-60 transition-opacity" />
          <p className="text-sm">Add the games that inspired you</p>
          <p className="text-xs mt-1 opacity-60">Every great game designer knows their influences</p>
        </button>
      )}

      {/* Reverse Engineer dialog */}
      <Dialog open={Boolean(reverseTarget)} onOpenChange={(o) => !o && setReverseTarget(null)}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Wand2 className="h-5 w-5 text-violet-400" />
              Reverse engineer "{reverseTarget?.name}"
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-2">
            <p className="text-sm text-muted-foreground">
              AI will study <span className="text-foreground font-medium">{reverseTarget?.name}</span>'s design DNA and spin up a brand-new, original game inspired by it — not a copy.
            </p>
            {reverseTarget?.gameData?.keyMechanics?.length ? (
              <div>
                <p className="text-[10px] uppercase tracking-wider font-semibold text-muted-foreground mb-1.5">Mechanics it'll riff on</p>
                <div className="flex flex-wrap gap-1.5">
                  {reverseTarget.gameData.keyMechanics.map((m, i) => (
                    <span key={i} className="text-xs bg-violet-500/10 border border-violet-500/20 text-violet-300 px-2 py-0.5 rounded-full">{m}</span>
                  ))}
                </div>
              </div>
            ) : null}
            <div className="space-y-1.5">
              <Label className="text-sm">Give it a direction (optional)</Label>
              <Textarea
                rows={3}
                placeholder={`e.g. "Make it faster and more chaotic" or "Set it in ancient Rome with political intrigue"`}
                value={reverseDirection}
                onChange={(e) => setReverseDirection(e.target.value)}
                className="resize-none"
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setReverseTarget(null)}>Cancel</Button>
            <Button
              className="gap-2 bg-violet-600 hover:bg-violet-700"
              onClick={reverseEngineer}
              disabled={reversing}
            >
              {reversing
                ? <><Loader2 className="h-4 w-4 animate-spin" /> Building your game…</>
                : <><Wand2 className="h-4 w-4" /> Build new game <ArrowRight className="h-4 w-4" /></>}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

