838	
839	  const [search, setSearch] = useState("");
840	  const [showAdd, setShowAdd] = useState(false);
841	  const [editing, setEditing] = useState<number | null>(null);
842	  const [form, setForm] = useState({ title: "", source: "", content: "", tags: "" });
843	
844	  const [showIngest, setShowIngest] = useState(false);
845	  const [ingestUrl, setIngestUrl] = useState("");
846	  const [ingestText, setIngestText] = useState("");
847	  const [ingesting, setIngesting] = useState(false);
848	
849	  const isFormOpen = showAdd || editing !== null;
850	
851	  const refresh = () => qc.invalidateQueries({ queryKey: getListResearchQueryKey(projectId) });
852	  const filtered = items?.filter(
853	    (i) => !search || (i.title + (i.content || "") + (i.tags || "")).toLowerCase().includes(search.toLowerCase())
854	  );
855	
856	  const closeForm = () => {
857	    setShowAdd(false);
858	    setEditing(null);
859	    setForm({ title: "", source: "", content: "", tags: "" });
860	  };
861	
862	  const openCreate = () => {
863	    setEditing(null);
864	    setForm({ title: "", source: "", content: "", tags: "" });
865	    setShowIngest(false);
866	    setShowAdd(true);
867	  };
868	
