            {game.gameData.designWeaknesses?.length ? (
              <div>
                <p className="text-[10px] uppercase tracking-wider font-semibold text-amber-400 mb-1.5">Watch out for</p>
                <ul className="space-y-1">
                  {game.gameData.designWeaknesses.map((w, wi) => (
